) as v(nombre, grupo_muscular, equipo, url_inicio, url_final, es_personalizado)
where not exists (
  select 1 from public.ejercicios e
  where e.nombre = v.nombre
    and e.grupo_muscular is not distinct from v.grupo_muscular
    and e.equipo is not distinct from v.equipo
);
